e"]=3,["te"]=0,["level"]=30,["rarityCost"]=2,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1203,["serverPending"]=true,["referenceDescription"]="Leap into the air upon demonic wings, moving a short distance. If you reactivate it within 1 sec you will leap again.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\ability_demonhunter_glide"},{["id"]=26001206,["name"]="Hand of Gul'dan",["class"]="Warlock",["spec"]="Destruction",["kind"]="Ability",["quality"]="Normal",["spells"]={954611},["ae"]=2,["te"]=0,["level"]=32,["rarityCost"]=0,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1206,["serverPending"]=true,["referenceDescription"]="Calls down a demonic meteor dealing Shadowflame damage to enemies within 5 yards and summons 4 Wild Imps which burst forth to attack the target for 10 sec.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\ability_warlock_handofguldan"},{["id"]=26001202,["name"]="Soul Harvest",["class"]="Warlock",["spec"]="Demonology",["kind"]="Ability",["quality"]="Epic",["spells"]={86395},["ae"]=2,["te"]=0,["level"]=36,["rarityCost"]=1,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1202,["serverPending"]=true,["referenceDescription"]="Increases your magic damage and your pets' damage by 15%. Lasts 6 sec, increased by 3 sec for each target afflicted by your Corruption, Curse of Agony, Immolate, Shadow Word: Pain and Devouring Plague, up to a maximum of 24 sec.\n\nDoes not stack with other similar effects.\n\nThis ability is usable while shapeshifted.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\spell_warlock_demonsoul"},{["id"]=26001604,["name"]="Soul Swap",["class"]="Warlock",["spec"]="Affliction",["kind"]="Ability",["quality"]="Epic",["spells"]={954614},["ae"]=2,["te"]=0,["level"]=28,["rarityCost"]=1,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1604,["serverPending"]=true,["referenceDescription"]="You copy your damage-over-time effects from the target, preserving their power and duration.\n\nFor 5 sec afterwards, the next target you cast Soul Swap: Exhale on will be afflicted by the copied damage-over-time effects.\n\nYou cannot Soul Swap to the same target.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\ability_warlock_soulswap"},{["id"]=26001204,["name"]="Unending Resolve",["class"]="Warlock",["spec"]="Demonology",["kind"]="Ability",["quality"]="Legendary",["spells"]={954512},["ae"]=2,["te"]=0,["level"]=42,["rarityCost"]=1,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1204,["serverPending"]=true,["referenceDescription"]="Hardens your skin, reducing all damage taken by 30% and preventing your spells from being interrupted or silenced for 6 sec.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\spell_shadow_demonictactics"},{["id"]=26001188,["name"]="Avatar",["class"]="Warrior",["spec"]="Arms",["kind"]="Ability",["quality"]="Legendary",["spells"]={86380},["ae"]=3,["te"]=0,["level"]=40,["rarityCost"]=2,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1188,["serverPending"]=true,["referenceDescription"]="Transform into an unstoppable colossus for 12 sec, causing you to deal 15% increased Physical damage and take 20% less damage.\n\nWhile in this state you move at 80% speed and it can't be reduced nor increased from that amount. You are also immune to immobilizing effects.\n\nShares a cooldown with Death Wish.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\warrior_talent_icon_avatar"},{["id"]=26001601,["name"]="Bloodbath",["class"]="Warrior",["spec"]="Fury",["kind"]="Ability",["quality"]="Epic",["spells"]={954814},["ae"]=2,["te"]=0,["level"]=42,["rarityCost"]=1,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1601,["serverPending"]=true,["referenceDescription"]="For the next 5 sec, causes your Physical melee abilities to deal (attack power*0.026+50) bleed damage over 5 sec and reduces the movement speed of the target by 30% for 3 sec. This ability shares a cooldown with Sweeping Strikes, and Blade Flurry.\n\nThis ability can be used while shapeshifted.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\ability_warrior_bloodbath"},{["id"]=26001187,["name"]="Colossus Smash",["class"]="Warrior",["spec"]="Arms",["kind"]="Ability",["quality"]="Rare",["spells"]={86361},["ae"]=2,["te"]=0,["level"]=30,["rarityCost"]=1,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1187,["serverPending"]=true,["referenceDescription"]="Smashes a target for 200% weapon damage, which ignores armor, to weaken their defenses, allowing your attacks to bypass 30% of their armor for 6 sec.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\ability_warrior_colossussmash"},{["id"]=26001612,["name"]="Demoralizing Banner",["class"]="Warrior",["spec"]="Arms",["kind"]="Ability",["quality"]="Epic",["spells"]={955062},["ae"]=2,["te"]=0,["level"]=32,["rarityCost"]=1,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1612,["serverPending"]=true,["referenceDescription"]="Throw down a war banner that decreases the armor of all enemies within 30 yards by 20% and their critical strike chance by 10%. Lasts 15 sec. This effect does not stack with similar effects.\n\nYou can Intervene to your war banner.\n\nThis ability can be used while shapeshifted.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\demoralizing_banner"},{["id"]=26001186,["name"]="Heroic Leap",["class"]="Warrior",["spec"]="Arms",["kind"]="Ability",["quality"]="Legendary",["spells"]={86358},["ae"]=3,["te"]=0,["level"]=30,["rarityCost"]=3,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1186,["serverPending"]=true,["referenceDescription"]="Leap through the air toward a target location, slamming down with destructive force to deal Physical damage and slow all enemies within 8 yards by 50% for 2 sec. While in the air you are immune to crowd control effects.\n\nUsable while shapeshifted.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\ability_heroicleap"},{["id"]=26001600,["name"]="Raging Blow",["class"]="Warrior",["spec"]="Fury",["kind"]="Ability",["quality"]="Normal",["spells"]={954836},["ae"]=2,["te"]=0,["level"]=28,["rarityCost"]=0,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1600,["serverPending"]=true,["referenceDescription"]="A mighty blow that deals 125% weapon damage from both melee weapons. Requires a weapon in the mainhand and off-hand to use. (Deals 15% reduced damage when used with Titan's Grip). \n\nBecoming Enraged enables one use of Raging Blow. You can store up to 2 charges.\n\nMultiple Raging Blow! charges cannot be gained within the same global cooldown.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\warrior_wild_strike"},{["id"]=26001616,["name"]="Siegebreaker",["class"]="Warrior",["spec"]="Fury",["kind"]="Ability",["quality"]="Epic",["spells"]={954876},["ae"]=2,["te"]=0,["level"]=40,["rarityCost"]=1,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1616,["serverPending"]=true,["referenceDescription"]="Use your full strength to slam the target with your weapon, dealing 200% weapon damage up to 5 nearby enemies in a conal attack.\n\nIf the target is a player, it also knocks them back. Enemies the target collides with are knocked back slightly and take 200% weapon damage.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\demoralizing_banner"},{["id"]=26001185,["name"]="Skull Banner",["class"]="Warrior",["spec"]="Arms",["kind"]="Ability",["quality"]="Epic",["spells"]={954514},["ae"]=3,["te"]=0,["level"]=40,["rarityCost"]=2,["requiredAE"]=0,["requiredTE"]=0,["requiredIDs"]="",["ascensionReference"]=1185,["serverPending"]=true,["referenceDescription"]="Throw down a war banner at your feet that increases the melee and ranged critical strike chance of party or raid members within 40 yards of the banner by 20%. Lasts 10 sec.\n\nAllies receiving this effect will become Fatigued and unable to benefit from Skull Banner for 180 sec.\n\nYou can Intervene to your war banner.\n\nThis ability is usable while shapeshifted.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\warrior_skullbanner"}}
for _,e in ipairs(A.AscensionAbilities)do
 assert(not A.byID[e.id],"Duplicate imported ability ID")
