for _,meta in ipairs({{["id"]=22954809,["referenceDescription"]="Finishing move that slashes at the flesh of all enemies within 8 yards, dealing Physical damage and causing them to bleed per combo point:\n   1 point: (4+level scaling*1+(spell power+attack power)*1*1*0.015+(spell power+attack power)*0.02) physical damage and ((14+level scaling*1+(spell power+attack power)*1*1*0.002+(spell power+attack power)*0.01)*4) bleed damage over 8 sec.\n   2 points: (4+level scaling*2+(spell power+attack power)*2*2*0.015+(spell power+attack power)*0.02) physical damage and ((14+level scaling*2+(spell power+attack power)*2*2*0.002+(spell power+attack power)*0.01)*4) bleed damage over 8 sec.\n   3 points: (4+level scaling*3+(spell power+attack power)*3*3*0.015+(spell power+attack power)*0.02) physical damage and ((14+level scaling*3+(spell power+attack power)*3*3*0.002+(spell power+attack power)*0.01)*4) bleed damage over 8 sec.\n   4 points: (4+level scaling*4+(spell power+attack power)*4*4*0.015+(spell power+attack power)*0.02) physical damage and ((14+level scaling*4+(spell power+attack power)*4*4*0.002+(spell power+attack power)*0.01)*4) bleed damage over 8 sec.\n   5 points: (4+level scaling*5+(spell power+attack power)*5*5*0.015+(spell power+attack power)*0.02) physical damage and ((14+level scaling*5+(spell power+attack power)*5*5*0.002+(spell power+attack power)*0.01)*4) bleed damage over 8 sec.",["referenceIcon"]="Interface\\AddOns\\HeroFreePick\\Art\\AscensionAbilities\\inv_knife_1h_cataclysm_c_05"},{["id"]=22954553,["referenceDescription"]="Finishing move that causes damage per combo point:\n   1 point  : (66+((level scaling*1)+attack power*0.056)*damage multiplier)-(66+((level scaling*1)+attack power*0.07)*damage multiplier) damage\n   2 points: (66+((level scaling*2)+attack power*0.112)*damage multiplier)-(66+((level scaling*2)+attack power*0.14)*damage multiplier) damage\n   3 points: (66+((level scaling*3)+attack power*0.168)*damage multiplier)-(66+((level scaling*